#!/usr/bin/env python3
"""Adds the 2.7 cosmetics and critters to assets/2d/world.png + world.json without re-baking the rest.
Everything here is drawn in code (same outline and palette habits as bake_world.py). Safe to re-run: it
replaces any 'x.' sprites it added before.

Run:  python3 tools2d/bake_extras.py [--sheet contact.png]
"""
import json, os, sys
from PIL import Image, ImageDraw

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, '..', 'assets', '2d')
OUTL = (36, 26, 32, 255)
WOOD, WOODL, WOODD = (150, 104, 62), (186, 136, 84), (104, 70, 44)
STONE, STONEL, STONED = (150, 146, 140), (186, 182, 176), (110, 106, 102)
GOLD, GOLDL, GOLDD = (220, 160, 53), (255, 214, 100), (150, 102, 0)
RED, GREEN, GREEND, BLUE, WHITE, BLACK = (190, 54, 48), (88, 160, 70), (56, 116, 52), (70, 130, 200), (238, 232, 220), (40, 34, 40)
CLOTH, CLOTHD, IRON, IROND = (130, 60, 70), (96, 40, 52), (128, 132, 142), (84, 88, 98)
SPR = {}


def outline(im):
    w, h = im.size
    out = Image.new('RGBA', (w + 2, h + 2), (0, 0, 0, 0))
    out.paste(im, (1, 1))
    src, px = out.copy().load(), out.load()
    for y in range(h + 2):
        for x in range(w + 2):
            if src[x, y][3]:
                continue
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < w + 2 and 0 <= ny < h + 2 and src[nx, ny][3]:
                    px[x, y] = OUTL
                    break
    return out


def D(key, w, h, ops):
    """ops: ('r', x0, y0, x1, y1, col) rect | ('e', ...) ellipse | ('p', pts, col) polygon | ('l', pts, col) line | ('.', pts, col) points."""
    im = Image.new('RGBA', (w, h), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    for op in ops:
        t = op[0]
        if t == 'r': d.rectangle(op[1:5], fill=op[5])
        elif t == 'e': d.ellipse(op[1:5], fill=op[5])
        elif t == 'p': d.polygon(op[1], fill=op[2])
        elif t == 'l': d.line(op[1], fill=op[2])
        elif t == '.': d.point(op[1], fill=op[2])
    SPR['x.' + key] = outline(im)


def lit(x0, y0, x1, y1, base, hi, lo):
    """A block with a lit top-left edge and a shaded bottom-right one."""
    return [('r', x0, y0, x1, y1, base), ('l', [(x0, y1), (x0, y0), (x1, y0)], hi), ('l', [(x0, y1), (x1, y1), (x1, y0)], lo)]


