def critter(key, w, h, body, f0, f1):
    """Two frames of a small animal, drawn facing right: body ops shared, f0/f1 are the legs (or whatever moves)."""
    D(key + '.0', w, h, body + f0)
    D(key + '.1', w, h, body + f1)


