def main():
    props()
    critters()
    sheet = Image.open(os.path.join(OUT, 'world.png')).convert('RGBA')
    meta = json.load(open(os.path.join(OUT, 'world.json')))
    old = [k for k in meta if k.startswith('x.')]
    base_h = min([meta[k][1] for k in old] + [sheet.height]) if old else sheet.height
    for k in old:
        del meta[k]
    W = sheet.width
    items = sorted(SPR.items(), key=lambda kv: (-kv[1].height, kv[0]))
    x, y, rowh, places = 0, base_h + 1, 0, []
    for k, im in items:
        if x + im.width + 1 > W:
            x, y, rowh = 0, y + rowh + 1, 0
        places.append((k, im, x, y))
        x += im.width + 1
        rowh = max(rowh, im.height)
    H = y + rowh + 1
    out = Image.new('RGBA', (W, H), (0, 0, 0, 0))
    out.paste(sheet.crop((0, 0, W, base_h)), (0, 0))
    for k, im, px, py in places:
        out.paste(im, (px, py))
        meta[k] = [px, py, im.width, im.height]
    out.save(os.path.join(OUT, 'world.png'), optimize=True)
    json.dump(meta, open(os.path.join(OUT, 'world.json'), 'w'), separators=(',', ':'))
    print(len(SPR), 'extra sprites;', 'sheet', out.size)
    if '--sheet' in sys.argv:
        p = sys.argv[sys.argv.index('--sheet') + 1]
        z = 4
        c = Image.new('RGBA', (W * z // 2, (H - base_h) * z), (96, 150, 80, 255))
        c.paste(out.crop((0, base_h, W // 2, H)).resize((W * z // 2, (H - base_h) * z), Image.NEAREST), (0, 0), out.crop((0, base_h, W // 2, H)).resize((W * z // 2, (H - base_h) * z), Image.NEAREST))
        c.save(p)


if __name__ == '__main__':
    main()
